/*
 * Accent presets: the one accent, swapped. <html data-accent="blue"> on any neutral preset
 * (data-theme) or the default greys. Each sits 3:1 off the canvas and floating surfaces and
 * carries a white label at 4.5:1, in light and dark; the contrast guard checks every one on
 * every neutral. `html` in the selector outranks the neutral presets, which set an ink accent.
 * None is red, green or amber: those already mean danger, success and "needs you".
 * Values from the theme studio. Want another? Pick it there and copy two lines per appearance.
 */
html[data-accent="blue"] { --primary: #2563eb; --primary-foreground: #ffffff; }
html.dark[data-accent="blue"] { --primary: #2866ee; --primary-foreground: #ffffff; }

html[data-accent="indigo"] { --primary: #5e6ad2; --primary-foreground: #ffffff; }
html.dark[data-accent="indigo"] { --primary: #5e6ad2; --primary-foreground: #ffffff; }

html[data-accent="violet"] { --primary: #7c3aed; --primary-foreground: #ffffff; }
html.dark[data-accent="violet"] { --primary: #8546f8; --primary-foreground: #ffffff; }

html[data-accent="pink"] { --primary: #da2677; --primary-foreground: #ffffff; }
html.dark[data-accent="pink"] { --primary: #da2677; --primary-foreground: #ffffff; }

html[data-accent="teal"] { --primary: #0e766e; --primary-foreground: #ffffff; }
html.dark[data-accent="teal"] { --primary: #1a7c74; --primary-foreground: #ffffff; }
